import subprocess as sp
def run(args, inp=b"", timeout=5):
    r = sp.run(['./executable']+args, input=inp, capture_output=True, timeout=timeout)
    return r.returncode, r.stdout, r.stderr
big = b"".join([f">s{i}\nACGT\n".encode() for i in range(5)])
def find_rs(seed, n=5):
