            out=run(['seq','-s',str(seed),'-f',repr(mid)], inp=big)[1]
            names=set(l.decode()[1:] for l in out.splitlines() if l.startswith(b">"))
            if f"s{idx}" in names:
                hi=mid
            else:
                lo=mid
        res.append(hi)
