    // From earlier: G1: 1111111101100001011100000100100100111100010100110101010100100010111100100000001111000010111101110110 (100? let's count, actually 100)
    return "1111111101100001011100000100100100111100010100110101010100100010111100100000001111000010111101110110";
}
