    std::string target = get_rb_pattern();
    int start=atoi(argv[1]), end=atoi(argv[2]);
    std::string mode=argv[3]; // "float" or "mod"
    for(int seed=start; seed<end; seed++) {
        std::mt19937_64 gen(seed);
        std::string bits="";
        for(int i=0;i<100;i++) {
            if(mode=="float") bits+= (gen()/(double)gen.max()<0.5?'1':'0');
