int main() {
    std::mt19937_64 gen(11);
    std::string high="", low="";
    for(int i=0;i<100;i++) {
        unsigned long long v=gen();
        // Need to regenerate? Actually gen() advances each call, so high and low from same call? For float vs mod, each call gives one value, but high vs low are different bits of same call.
        // To compare fairly, we need to generate separately: for high, use gen()/max<0.5 (high bit), for low, use gen()%2 (low bit), but each uses one gen() call.
        // Our loop above uses one gen() per iteration for both? Actually we need two separate runs.
        (void)v;
