    std::string h="", l="";
    for(int i=0;i<100;i++) h+= (g1()/(double)g1.max()<0.5?'1':'0');
    for(int i=0;i<100;i++) l+= (g2()%2==0?'1':'0');
    std::cout<<"high: "<<h<<"\n";
    std::cout<<"low:  "<<l<<"\n";
    return 0;
}
