static gzFile open_in(const char* fn){
    if(fn==NULL||strcmp(fn,"-")==0) return gzdopen(dup(fileno(stdin)),"r");
    return gzopen(fn,"r");
}
struct Record{ std::string name,comment,seq,qual; bool is_fq=false; };
struct Reader{
    gzFile fp=nullptr; std::string pending; bool has_pending=false; bool eof=false;
    Reader(gzFile f):fp(f){}
    bool getline_fp(std::string &out){
        out.clear(); if(eof) return false;
        char tmp[8192]; bool got=false; std::string acc;
        while(true){ char *r=gzgets(fp,tmp,sizeof(tmp)); if(r==NULL){ if(got) break; eof=true; return false; } got=true; acc+=tmp; if(!acc.empty()&&acc.back()=='\n') break; if(strlen(tmp)<sizeof(tmp)-1) break; }
        out=acc; while(!out.empty()&&(out.back()=='\n'||out.back()=='\r')) out.pop_back(); return true;
    }
    bool next(Record &rec){
        std::string line;
        while(true){ if(has_pending){line=pending;has_pending=false;} else{if(!getline_fp(line)) return false;} if(line.empty()) continue; if(line[0]=='>'||line[0]=='@') break; }
        char type=line[0]; std::string header=line.substr(1);
        std::string name,comment; size_t p=header.find_first_of(" \t");
        if(p==std::string::npos){name=header;comment="";} else{name=header.substr(0,p);comment=header.substr(p+1);}
        rec.name=name; rec.comment=comment; rec.seq.clear(); rec.qual.clear(); rec.is_fq=(type=='@');
        if(type=='>'){
            while(true){ std::string nl; if(!getline_fp(nl)) break; if(!nl.empty()&&(nl[0]=='>'||nl[0]=='@')){pending=nl;has_pending=true;break;} rec.seq+=nl; }
        }else{
            std::string first; if(!getline_fp(first)) return false; rec.seq=first;
            std::string plus; bool found=false;
            while(true){ std::string nl; if(!getline_fp(nl)) return false; if(!nl.empty()&&nl[0]=='+'){plus=nl;found=true;break;} rec.seq+=nl; }
            if(!found) return false;
            rec.qual.clear();
            while((int)rec.qual.size()<(int)rec.seq.size()){ std::string ql; if(!getline_fp(ql)) break; rec.qual+=ql; }
            if((int)rec.qual.size()!=(int)rec.seq.size()) return next(rec);
        }
        return true;
    }
};
