static int stk_seq(int argc, char *argv[]){
    bool o_a=false,o_A=false,o_C=false,o_c=false,o_r=false,o_R=false,o_S=false,o_U=false,o_V=false,o_x=false,o_1=false,o_2=false,o_N=false;
