    std::vector<std::string> pos;
    for(int i=2;i<argc;i++){
        char *arg=argv[i];
        if(arg[0]!='-'||strcmp(arg,"-")==0){ pos.push_back(arg); }
        else if(strcmp(arg,"--")==0){ for(int j=i+1;j<argc;j++) pos.push_back(argv[j]); break; }
        else{
            for(size_t k=1;arg[k]!='\0';k++){
                char o=arg[k];
                bool need=false; if(o=='l'||o=='n'||o=='q'||o=='s'||o=='f'||o=='F'||o=='L'||o=='M'||o=='Q'||o=='X') need=true;
                if(o=='a'){o_a=true;} else if(o=='A'){o_A=true;} else if(o=='C'){o_C=true;} else if(o=='c'){o_c=true;}
                else if(o=='r'){o_r=true;} else if(o=='R'){o_R=true;} else if(o=='S'){o_S=true;} else if(o=='U'){o_U=true;}
                else if(o=='V'){o_V=true;} else if(o=='x'){o_x=true;} else if(o=='1'){o_1=true;} else if(o=='2'){o_2=true;}
                else if(o=='N'){o_N=true;}
                else if(need){
                    std::string val;
                    if(arg[k+1]!='\0'){val=std::string(arg+k+1); k=strlen(arg)-1;}
                    else{ if(i+1>=argc){fprintf(stderr,"seq: option requires an argument -- '%c'\n",o); val="";} else{val=argv[++i]; break;} }
                    if(o=='l')o_l=atoi(val.c_str());
                    else if(o=='n'){o_n=val;h_n=true;}
                    else if(o=='q'){o_q=atoi(val.c_str());h_q=true;}
                    else if(o=='s')o_s=atoi(val.c_str());
                    else if(o=='f'){o_f=atof(val.c_str());h_f=true;}
                    else if(o=='F'){o_F=val.empty()?0:val[0];h_F=true;}
                    else if(o=='L'){o_L=atoi(val.c_str());h_L=true;}
                    else if(o=='M'){o_M=val;h_M=true;}
                    else if(o=='Q')o_Q=atoi(val.c_str());
                    else if(o=='X'){o_X=val;h_X=true;}
                    break;
                } else { fprintf(stderr,"seq: invalid option -- '%c'\n",o); }
            }
        }
    }
    const char* fn=pos.empty()?NULL:pos[0].c_str();
    gzFile fp=open_in(fn);
    if(fp==NULL){fprintf(stderr,"[E::stk_seq] failed to open the input file/stream.\n"); return 1;}
    std::map<std::string,std::vector<std::pair<int,int>>> bed;
    if(h_M){
        gzFile bfp=gzopen(o_M.c_str(),"r");
        if(bfp){
            char lb[8192];
            while(gzgets(bfp,lb,sizeof(lb))){
                std::string line=lb; while(!line.empty()&&(line.back()=='\n'||line.back()=='\r')) line.pop_back(); if(line.empty()) continue;
                std::vector<std::string> f; size_t s=0;
                while(s<line.size()){while(s<line.size()&&isspace((unsigned char)line[s]))s++; if(s>=line.size())break; size_t e=s; while(e<line.size()&&!isspace((unsigned char)line[e]))e++; f.push_back(line.substr(s,e-s)); s=e;}
                if(f.size()<3) continue;
                int b=atoi(f[1].c_str()), e=atoi(f[2].c_str()); if(e>b) bed[f[0]].push_back({b,e});
