                std::string pat=s.compare(i,6,pat1)==0?pat1:pat2;
                // extend while next 6 matches same pat (allow 1 mismatch? For simplicity, exact)
                while(j+6<=s.size()&&s.compare(j,6,pat)==0) j+=6;
